window.__BUNDLE__={"generatedAt":"2026-08-25T19:15:32.803782+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-18","archiveCutoff":"2021-08-26","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":208,"arxiv":1221,"total":1429},"freshness":{"latestPaperDate":"2026-08-25","latestPublishedDate":"2026-08-25","latestBatchCount":462,"newInLast24h":526,"newInLast48h":776},"historyTotal":8733,"topicCounts":{"Multi-Agent":1666,"Evaluation":4408,"Planning":802,"Memory":198,"Code Agent":461,"Interpretability":298,"Agentic RAG":918,"Agentic Search":1110,"RL for LLM":685,"Reasoning":2783,"Hallucination":543,"Post-Training":1273,"Alignment":1155,"World Model":93,"Tool Use":1000,"Agent Safety":1958,"Computer Use":197,"Reflection":390,"VLM Training":395,"LLM Training":936,"Fine-tuning":1259,"Multimodal Agent":56,"Agent Framework":608,"Error Attribution":79,"Data Engine":192},"count":36,"recentTotal":1737,"archiveCount":0,"archiveTotal":6996,"sources":{"hf":59,"arxiv":1674,"semanticScholar":4},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"topics":["Planning","World Model"],"source":"hf","title":"WorldMind: Decoupled Game World Model for State-Aware NPC Behavior","upvotes":13,"id":"arxiv:2608.21439","hfUrl":"https://huggingface.co/papers/2608.21439","announceDate":"2026-08-25","submittedDate":"2026-08-18","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21439.pdf","url":"https://arxiv.org/abs/2608.21439","arxiv":"https://arxiv.org/abs/2608.21439","tags":["Planning","World Model"],"authors":["Zhiyang Deng","Boran Zhang","Danze Chen","Yeying Jin"],"abstract":"Game world models have recently demonstrated promising capabilities in generating visually coherent and action-controllable gameplay videos. However, non-player character (NPC) behavior in existing models is either implicitly entangled with video generation or explicitly prescribed through external control signals. Consequently, a game world model has to jointly understand the state, plan the NPC's response and render its visual outcome, limiting its ability to produce responsive and state-aware NPC behavior. The challenge lies in the lack of an explicit interface for state-grounded decision-making. To this end, we introduce WorldMind, to our knowledge the first decoupled framework for state-aware NPC behavior in game world models. WorldMind separates interactive world modeling into four layers: an Understanding Layer that constructs a compact state from generated frames; a Decision Laye"},{"topics":["Reasoning","Evaluation"],"source":"hf","title":"One Polluted Page Is Enough: Evaluating Web Content Pollution in LLM Recommenders","upvotes":4,"id":"arxiv:2606.13610","hfUrl":"https://huggingface.co/papers/2606.13610","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2606.13610.pdf","url":"https://arxiv.org/abs/2606.13610","arxiv":"https://arxiv.org/abs/2606.13610","tags":["Reasoning","Evaluation"],"authors":["Minghao Luo","Liang Chen"],"abstract":"Search-augmented LLMs increasingly mediate everyday consumer recommendations by retrieving live web content. This creates a new risk: LLM recommenders may consume web content that Generative Engine Optimization (GEO) operators have polluted to mislead them. We ask: to what extent do they become unwitting promoters of fake products? We introduce FORGE (Fake Online Recommendations in Generative Environments), which locally rewrites real products in a frozen set of retrieved web pages into fake ones and measures how often the LLM recommends the fake product, across 225 real products in 15 categories and 5 consumer scenarios. Across 12 commercial and open-weights LLMs, all models are vulnerable: a single polluted page yields fooled rates of up to 27%, while the full top-3 replacement raises this to 73.8%. Vulnerability varies across categories, increasing when models lack stable prior knowle"},{"topics":["Planning"],"source":"arxiv","title":"Apodex 1.1: Scaling Agentic Intelligence for Complex Work","upvotes":169,"id":"arxiv:2608.23283","hfUrl":"https://huggingface.co/papers/2608.23283","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23283.pdf","url":"https://arxiv.org/abs/2608.23283","arxiv":"https://arxiv.org/abs/2608.23283","tags":["Planning"],"authors":["Apodex Team","B. An","B. Li","B. Wang","B. Zhang","B. L. Wang","C. Feng","C. Wei","C. Xue","C. Zhang","D. Ng","D. Ye","E. Min","F. Chen","F. Liu","F. Yang","F. Ye","H. Xu","H. Yang","H. Ye","H. Zhang","H. Zhao","J. Li","J. Lin","J. Xia","K. Jin","K. Wang","K. Yang","L. Bing","L. Lei","L. Su","Le. Wang","Lu. Wang","N. Wang","Q. Ren","Q. Yang","R. Li","S. Bai","S. Du","S. Li","S. Lin","S. Nie","S. Wang","S. Zhang","S. Z. Wang","Ta. Q. Fang","Ti. Q. Fang","W. Fang","W. Li","W. Zhang","X. Chen","X. Li","X. Tang","X. Wang","X. Xu","X. Zhang","X. Q. Wang","X. Y. Wang","Y. Deng","Y. Gao","Y. Hu","Y. Li","Y. Sui","Y. Wang","Y. Xiao","Y. Zhang","Z. Chen","Z. Cheng","Z. Feng","Z. Liang","Z. Zhang"],"abstract":"General-purpose language models can reason and synthesize knowledge, but complex work also requires sustained interaction with files, information sources, and executable code, together with state maintenance, failure recovery, and verifiable delivery. We call this \\emph{working capability}: sustained, verifiable progress toward a real-world objective. Apodex 1.1 develops this capability along two complementary dimensions. \\emph{Environment Scaling} expands the diversity and verifiability of executable file, search, and code environments, while \\emph{Agentic Coordination Scaling} trains agents to decompose long-horizon tasks, delegate parallel work, integrate asynchronous results, and replan. A shared execution harness and AgentOS maintain task state and provenance across tools and agents, and training turns environment trajectories and coordination traces into reliable behavior. Across c"},{"topics":["Multi-Agent","Tool Use","Planning","Evaluation"],"source":"arxiv","title":"MobilePA-Bench: Benchmarking Mobile Planner Agents on Complex Real-World Tasks","upvotes":33,"id":"arxiv:2608.23035","hfUrl":"https://huggingface.co/papers/2608.23035","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23035.pdf","url":"https://arxiv.org/abs/2608.23035","arxiv":"https://arxiv.org/abs/2608.23035","tags":["Multi-Agent","Tool Use","Planning","Evaluation"],"authors":["Yi Zhu","Xiongwei Wu","Qiyi Wang","Tingyu Qu","Jiajun Liu","Sihan Cao","Long Chen","Weigao Sun","Feida Zhu","Yiran Zhong","Steven Hoi"],"abstract":"As on-device LLM agents evolve into personal copilots, the mobile operating system has become a key testbed for this paradigm, making rigorous capability evaluation essential. Yet existing benchmarks fall into two camps, each with a critical blind spot: GUI-centric benchmarks test surface-level screen manipulation while overlooking background tool use and long-horizon planning, whereas static function-calling benchmarks rely on offline API matching that is detached from real runtime constraints. To close this gap, we present \\textbf{MobilePA-Bench}, an interactive, stateful, and tool-centric benchmark for evaluating the tool-calling and planning abilities of mobile planning agents. MobilePA-Bench runs on an executable sandbox that maintains live application databases and returns structured feedback, spanning $13$ functional domains and $212$ realistic mobile tools. Beyond basic tool use,"},{"topics":["Multi-Agent","Evaluation"],"source":"arxiv","title":"Prime Agent: A Self-Improving RLM Harness","upvotes":31,"id":"arxiv:2608.23552","hfUrl":"https://huggingface.co/papers/2608.23552","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23552.pdf","url":"https://arxiv.org/abs/2608.23552","arxiv":"https://arxiv.org/abs/2608.23552","tags":["Multi-Agent","Evaluation"],"authors":["Seth Karten","Alex L. Zhang","Kevin Thomas","Sebastian Müller","Elie Bakouch","Daniel Auras","Mika Senghaas","Fares Obeid","Konstantin Dunas","Johannes Hagemann","Sami Jaghouar"],"abstract":"Language models are sequential processors, but long-horizon agency requires external information and computation beyond model weights and active context. Prime Agent is an open-source harness for long-horizon evaluation and coding-agent workflows. A persistent IPython REPL follows the Recursive Language Model abstraction for programmatic context processing and test-time compute, while Continual Harness preserves histories, memories, skills, prompts, and subagent specifications across trajectories. Recursive subagents coordinate through direct agent-to-agent communication, and the Agents View lets humans inspect and manage daemon-backed sessions. Prime Agent standardizes execution, recovery, verification, and resource accounting while leaving strategy construction to the model. This low-friction, expressive membrane prevents harness failures from becoming model failures and pushes measure"},{"topics":["Post-Training","Reasoning","Evaluation"],"source":"arxiv","title":"Beyond the Stability-Exploration Dilemma: Environmental Regularization for LLM Policy Optimization","upvotes":14,"id":"arxiv:2608.23311","hfUrl":"https://huggingface.co/papers/2608.23311","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23311.pdf","url":"https://arxiv.org/abs/2608.23311","arxiv":"https://arxiv.org/abs/2608.23311","tags":["Post-Training","Reasoning","Evaluation"],"authors":["Xianlei Zhou","Xiangdi Meng","Yu He","Tianyu Qi","Shuyan Guan","Xianli Zhang","Jian Zhang","Xin Li","Qika Lin","Jun Liu"],"abstract":"Policy optimization (PO) for Large Language Models faces a stability--exploration trade-off, currently mediated by an action-side Policy-KL regularizer. This puts practitioners in a double bind: keeping Policy-KL constrains response behavior and consumes the action-side exploration budget, while dropping it leaves the optimization without an explicit drift control. We argue for an alternative that breaks the dilemma by moving regularization to the input side. As training progresses, the distribution over training queries induced by the current policy drifts unchecked from its pre-RL reference distribution. Concretely, Environment-Regularized Policy Optimization (ERPO) introduces a Query-KL (QKL) term that bounds this query distribution shift, together with a dataset-static reference-derived per-query weight that biases each per-query update toward queries typical under the reference. The"},{"topics":["Code Agent","Evaluation"],"source":"arxiv","title":"GameXpert-Bench: How Far Are Coding Agents from Expert Game Development?","upvotes":11,"id":"arxiv:2608.21833","hfUrl":"https://huggingface.co/papers/2608.21833","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21833.pdf","url":"https://arxiv.org/abs/2608.21833","arxiv":"https://arxiv.org/abs/2608.21833","tags":["Code Agent","Evaluation"],"authors":["Kun Chen","Haorong Hong","Peizhong Gao","Jianfeng Lin","Tongxu Luo","Yuxuan Xie","Chenxu Liu","Jieling He","Zhongyuan Liu","Zeno Zeng"],"abstract":"Recent large language models (LLMs) can operate as coding agents that build complete games from natural language requests. Game development is especially demanding because program logic, visual and audio content, interfaces, interaction and playability must function together in one executable artifact. Measuring this capability therefore requires evaluation of both game product and the development process. Existing benchmarks often assess the game development capabilities of LLMs by evaluating the final artifact or an isolated development stage. Our analysis of complete human-agent development trajectories identifies three stages that together span the lifecycle of game development with a coding agent: initial game generation, bug diagnosis and repair, and optimization over multiple turns. Therefore, we introduce GameXpert-Bench, which operationalizes the three lifecycle stages as three "},{"topics":["Reasoning","Code Agent","Evaluation"],"source":"arxiv","title":"LongWoF-Bench: Evaluating EvoMap Genes for Verifiable Long-Workflow Tasks","upvotes":5,"id":"arxiv:2608.23200","hfUrl":"https://huggingface.co/papers/2608.23200","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23200.pdf","url":"https://arxiv.org/abs/2608.23200","arxiv":"https://arxiv.org/abs/2608.23200","tags":["Reasoning","Code Agent","Evaluation"],"authors":["Xiao Zhang","Qumeng Sun","Jihao Li","Yiming Ren","Xiang Liu","Haoyang Zhang","Junjie Wang"],"abstract":"Large language models are increasingly expected to execute complex workflows whose success depends on maintaining interdependent constraints and producing artifacts that satisfy strict end-to-end verification. Yet successful execution experience is typically lost after a single run, forcing subsequent models to rediscover strategies and failure modes from scratch. We study whether such experience can instead be externalized and reused through EvoMap, where verifier-confirmed execution trajectories are consolidated into structured Gene. To evaluate this setting, we introduce the Long-Workflow Benchmark (LongWoF-Bench), comprising 778 machine-verifiable tasks across code generation, agent-environment synthesis, mathematical reasoning, and rule following. On the 252 tasks with verifier-confirmed Opus trajectories, evolved EvoMap Gene outperform Skill across all seven evaluated models by 8.7"},{"topics":["Agentic RAG","Agentic Search","Evaluation"],"source":"arxiv","title":"Better Retrieval, Worse Robustness:How Multi-hop RAG Amplifies Upstream ASR Errors","upvotes":5,"id":"arxiv:2608.22872","hfUrl":"https://huggingface.co/papers/2608.22872","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22872.pdf","url":"https://arxiv.org/abs/2608.22872","arxiv":"https://arxiv.org/abs/2608.22872","tags":["Agentic RAG","Agentic Search","Evaluation"],"authors":["Zhenghua Bao"],"abstract":"Speech-based applications pass spoken queries through automatic speech recognition (ASR) before any retrieval module, so ASR errors enter the pipeline as a fixed upstream constraint. We empirically test whether two extensions to standard retrieval-augmented generation (RAG), entity-graph linking and iterative reformulation, absorb or amplify these errors. Using four English accents synthesized through neural TTS, we evaluate four RAG configurations on three multi-hop QA benchmarks (HotpotQA, 2WikiMultiHopQA and MuSiQue) against a clean-text oracle. Although the structurally richer configurations generally retain higher absolute F1 under ASR input, both extensions amplify the error: the F1 gap from clean text to the highest-WER accent is 36-67% larger under their combination than under naive dense retrieval, on all three benchmarks. The dominant failure mode is corruption of one or more q"},{"topics":["LLM Training","Evaluation","Fine-tuning"],"source":"arxiv","title":"Industrial-Instruction: An End-to-End Framework for Building Instruction-Tuning and Benchmark Datasets from Industrial Technical Reports","upvotes":4,"id":"arxiv:2608.22817","hfUrl":"https://huggingface.co/papers/2608.22817","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22817.pdf","url":"https://arxiv.org/abs/2608.22817","arxiv":"https://arxiv.org/abs/2608.22817","tags":["LLM Training","Evaluation","Fine-tuning"],"authors":["Parsa Bakhtiari","Hassan Bashiri","Alireza Khalilipour","Masoud Nasiripour","Moharram Challenger"],"abstract":"Industrial technical reports contain high-value knowledge for maintenance, troubleshooting, and product engineering, but their heterogeneous structure (dense prose, specifications, tables) makes them difficult to index and reason over with standard retrieval and QA pipelines, and no public instruction-tuning or benchmark datasets are built from such documents. We address this gap with Industrial-Instruction, contributing (i) two open QA datasets built from real industrial technical reports and (ii) the end-to-end pipeline that produces them. Using 906 public Panasonic documents (7,525 pages), we apply layout-aware extraction, build a semantic retrieval index, and synthesize multiple-choice QA grounded in retrieved evidence under five query-document relationships (irrelevant retrieval, single-/multi-document support, single-/multi-document answer). After filtering an initial 23.9k generat"},{"topics":["Agentic RAG","Agentic Search"],"source":"arxiv","title":"The Laws of Context Allocation: Causal Measurement and Closed-Loop Orchestration in Generative Search","upvotes":3,"id":"arxiv:2608.23252","hfUrl":"https://huggingface.co/papers/2608.23252","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23252.pdf","url":"https://arxiv.org/abs/2608.23252","arxiv":"https://arxiv.org/abs/2608.23252","tags":["Agentic RAG","Agentic Search"],"authors":["Peiyang Liu","Xi Wang","Di Liang","Wei Ye"],"abstract":"As Retrieval-Augmented Generation (RAG) shifts toward diverse portfolio generation, it is stymied by two critical bottlenecks: flawed measurement of evidence utilization, and suboptimal context budget allocation. We resolve both sequentially. To resolve measurement, we expose a pervasive ``diagnostic illusion'': standard relevance proxies fail catastrophically on hard negatives. We replace them with an efficient causal leave-one-out probe that accurately isolates generative reliance and formally calibrates the structural dilution of LLM attention. To resolve allocation, we deploy this causal probe in a deconfounded factorial grid. We prove that the prevailing strategy of monolithic context widening is an architectural trap penalized by relevance decay. Instead, allocating compute iteratively across multiple sequential generations drives transformative portfolio recall gains of 16.7--20.5"},{"topics":["Evaluation","World Model"],"source":"arxiv","title":"From Generation to Simulation: How Far Are World Models from Being True Simulators?","upvotes":3,"id":"arxiv:2608.23070","hfUrl":"https://huggingface.co/papers/2608.23070","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23070.pdf","url":"https://arxiv.org/abs/2608.23070","arxiv":"https://arxiv.org/abs/2608.23070","tags":["Evaluation","World Model"],"authors":["Tong Wang","Huan Deng","Mucheng Yang","Yang He","Xiaohui Kuang","Gang Zhao"],"abstract":"With the rapid progress of diffusion models and large-scale video generation, generative world models are increasingly expected to replace traditional simulators, including physics engines, game engines, and reinforcement-learning environments. Yet the remaining distance from generation to simulation lacks a systematic assessment. We present a capability-based study using an external yardstick: eight capabilities of a traditional simulator, namely asset construction, physics engine, interaction, controllability, stability, state feedback, diversity, and evaluation metrics. We trace three main technical routes--latent dynamics, video generation, and joint-embedding prediction--and map exactly 200 representative works published from 2018 to June 2026 onto these capabilities. Our analysis shows that world models have achieved functional substitution in interaction and controllability for sp"},{"topics":["Agentic Search"],"source":"arxiv","title":"Same Agent, Different Answers: A Repeat-Aware Audit of Corpus-Induced Answer Churn in Retrieval-Augmented QA","upvotes":3,"id":"arxiv:2608.22856","hfUrl":"https://huggingface.co/papers/2608.22856","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22856.pdf","url":"https://arxiv.org/abs/2608.22856","arxiv":"https://arxiv.org/abs/2608.22856","tags":["Agentic Search"],"authors":["Jingjie Ning","Xueqi Li"],"abstract":"A retrieval-augmented QA system can return different answers after an index expansion even when its requested model identifier, prompt, retrieval policy, evidence depth, rendering, and exposed generation controls are held fixed. Aggregate accuracy may hide these changes when gains and losses cancel, while ordinary generation variability makes one-shot comparisons overstate update effects. We call the hidden phenomenon accuracy-blind answer churn and introduce the \\emph{Snapshot Compatibility Audit}, which estimates excess answer churn by subtracting same-snapshot repeat disagreement from cross-snapshot disagreement. We instantiate it by expanding one frozen FineWeb prefix from one to seven shards. In a preregistered 400-question Natural Questions study, normalized-exact and blinded-semantic excess churn are 6.44 and 10.25 percentage points while exact-match accuracy changes by only $-1.5"},{"topics":["Error Attribution","Evaluation","Alignment"],"source":"arxiv","title":"ClawProBench: Trace-Aware Evaluation of AI Agents with Runtime Coverage and Frozen Workplace-Style Holdouts","upvotes":2,"id":"arxiv:2608.22510","hfUrl":"https://huggingface.co/papers/2608.22510","announceDate":"2026-08-25","submittedDate":"2026-08-23","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22510.pdf","url":"https://arxiv.org/abs/2608.22510","arxiv":"https://arxiv.org/abs/2608.22510","tags":["Error Attribution","Evaluation","Alignment"],"authors":["YuanHang Xiao"],"abstract":"Agent benchmarks often evaluate only final answers even when agents run on stateful runtimes. We argue this under-specifies what is being evaluated: the proper unit is a declared model-plus-runtime configuration whose failures can occur in evidence acquisition, runtime routing, safety boundaries, or repeated execution. We present ClawProBench, a trace-aware benchmark for runtime-native agent evaluation instantiated on OpenClaw, a live agent runtime with workspace tools and native surfaces for browsing, memory, messaging, scheduling, skills, and subagents. ClawProBench defines two tracks: a 102-scenario full profile with live workspace and native-runtime routing tasks, and a frozen 68-scenario holdout with closed-world JSON output contracts for robust ranking. Trials are scored from execution traces via a safety-gated formula combining correctness, process quality, and efficiency, preserv"},{"topics":["VLM Training","Evaluation","Alignment"],"source":"arxiv","title":"EXPL-FR: Explaining Face Recognition Models via Vision-Language Alignment","upvotes":1,"id":"arxiv:2608.21486","hfUrl":"https://huggingface.co/papers/2608.21486","announceDate":"2026-08-25","submittedDate":"2026-08-21","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21486.pdf","url":"https://arxiv.org/abs/2608.21486","arxiv":"https://arxiv.org/abs/2608.21486","tags":["VLM Training","Evaluation","Alignment"],"authors":["Guray Ozgur","Mustafa Efe Tamyapar","Naser Damer","Fadi Boutros"],"abstract":"Deep face recognition (FR) models reach near-saturated accuracy but remain opaque: a practitioner cannot ask which semantic attributes a similarity score relied upon. EXPL-FR answers this inside the FR model's own embedding space. A lightweight adapter aligns a vision-language model's (VLM) image encoder with the frozen FR space, trained on face images alone and never on text. Because the VLM's encoders share one space, the same adapter applies to the text encoder, turning 978 attribute prompts in 22 categories, also extendable, into FR-space anchors at no extra cost. We do not assume this transfer works: a face-verification protocol measures it, and an ablation changing only the adapter isolates its contribution. Not every concept survives, because an FR model earns its invariances by discarding the factors it must verify identities across. A label-free detectability measure compares ea"},{"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","Reflection"],"source":"arxiv","title":"SRPO: Self-Reflective Policy Optimization for Long-Horizon Reasoning","upvotes":0,"id":"arxiv:2608.23493","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23493.pdf","url":"https://arxiv.org/abs/2608.23493","arxiv":"https://arxiv.org/abs/2608.23493","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Jialong Liu","Yuling Shi","Ning Yang","Xiaodong Gu","Zuchao Li"],"abstract":"Self-reflection is a powerful mechanism for credit assignment in human learning, converting sparse outcome feedback into actionable guidance. However, its potential for post-training Large Language Models (LLMs) remains underexplored. We propose Self-Reflective Policy Optimization (SRPO), a framework that internalizes this capability. SRPO enables LLMs to analyze their own completed trajectories, synthesize errors into concise \"reflection patches,\" and use reflection-conditioned teacher scores on student on-policy rollouts as dense token-level training signals. This process effectively transforms sparse terminal supervision into dense, token-level learning signals without requiring external critics, separate reward models, or larger teacher models. We demonstrate that SRPO achieves state-of-the-art performance across mathematical reasoning and long-horizon agentic benchmarks with excepti"},{"topics":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"source":"arxiv","title":"GTA-RAG: Graph-Trajectory-Augmented Reinforcement Learning for Multi-Turn Retrieval-Augmented Reasoning","upvotes":0,"id":"arxiv:2608.22479","announceDate":"2026-08-25","submittedDate":"2026-08-23","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22479.pdf","url":"https://arxiv.org/abs/2608.22479","arxiv":"https://arxiv.org/abs/2608.22479","tags":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation"],"authors":["Jun Chen","Yongchao Liu","Pengyu Qiu","Jiajun Zheng","Juelu Zhang","Yujie Zeng","Qin Zhang","Ziyue Qiao","Xiao Luo"],"abstract":"Retrieval-augmented generation (RAG) enables LLMs to access external knowledge for answering knowledge-intensive questions. For complex multi-hop questions, multi-turn retrieval-augmented reasoning extends RAG into an iterative process that repeatedly searches for and integrates evidence across documents. However, existing reinforcement-learning (RL) approaches for agentic RAG are typically optimized with final-answer rewards, which provide sparse supervision and overlook whether the model actually retrieves the required evidence chain. We present \\textsc{GTA-RAG}, a graph-trajectory-augmented RL framework for multi-turn retrieval-augmented reasoning. From an entity--document graph, we sample connected document paths, synthesize multi-hop QA trajectories, and validate them with the deployed retriever to obtain executable trajectory-level supervision. We then optimize the retrieval policy"},{"topics":["Multi-Agent","Tool Use","Reasoning","Fine-tuning","RL for LLM","Agent Framework"],"source":"arxiv","title":"Small Reasoning Models are Instruction Followers in Function Calling","upvotes":0,"id":"arxiv:2608.22472","announceDate":"2026-08-25","submittedDate":"2026-08-23","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22472.pdf","url":"https://arxiv.org/abs/2608.22472","arxiv":"https://arxiv.org/abs/2608.22472","tags":["Multi-Agent","Tool Use","Reasoning","Fine-tuning","RL for LLM"],"authors":["Yalda Taheri","Mohammad Hassan Heydari","Erfan Naaman","Afsaneh Fatemi"],"abstract":"Function calling represents the core capability of agentic large language models (LLMs). Existing research has focused on enhancing LLMs function-calling accuracy through fine-tuning, reinforcement learning (RL), and multi-agent frameworks, particularly for native function-calling LLMs. This work demonstrates that LLMs achieve superior accuracy in function calling in instruction-following contexts (i.e., standard user-assistant interactions) rather than a tool calling context. We introduce Instruction-Followed Function Calling (IFFC), a novel framework that decouples function-calling logic from the primary LLM and delegates it to a dedicated smaller model operating within the instruction-following paradigm. Our method consistently outperforms both native function calling (NFC) and prompt-based function calling (PFC) baselines, with particularly strong gains on reasoning-oriented LLMs. Fu"},{"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability","Fine-tuning"],"source":"arxiv","title":"Enhancing Group Recommendation with Memory-Augmented Reasoning in LLM Agent","upvotes":0,"id":"arxiv:2608.21939","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21939.pdf","url":"https://arxiv.org/abs/2608.21939","arxiv":"https://arxiv.org/abs/2608.21939","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability"],"authors":["Qimeng Niu","Bowen Hao","Zixuan Zhang","Shuyu Qu","Hongzhi Yin"],"abstract":"The core challenge in group recommendation lies in modeling the dynamic evolution of user preferences and explain?ing the consensus formation process. Existing Large Language Model (LLM)-based methods, despite improved interpretability, treat interaction history as fixed text, ignoring the natural evolution of group/user preferences over time, and lacking explicit modeling of the complex group decision-making process. To address these issues, we propose AGR, a LLM-based agent, which consists of a Memory Module and a Reasoning Module. The Memory Module employs a token-based hash table to dynamically manage the historical interactions of groups and users. This design supports fundamental operations including insertion, updating, retrieval, forgetting of irrelevant records, and summarization of evolving group and user profiles for efficiently tracking. Based on these retrieved dynamic profi"},{"topics":["Post-Training","Reasoning","Hallucination","Evaluation","Alignment","RL for LLM"],"source":"arxiv","title":"BioMed-Agent-RL: A Meta Learning, All You Need for Biomedical Applications","upvotes":0,"id":"arxiv:2608.21864","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21864.pdf","url":"https://arxiv.org/abs/2608.21864","arxiv":"https://arxiv.org/abs/2608.21864","tags":["Post-Training","Reasoning","Hallucination","Evaluation","Alignment"],"authors":["Md Asaduzzaman Jabin","Zihao Wu","Tianming Liu"],"abstract":"The current progress of Clinical Vision Large Language Models (C-VLLMs) has substantially improved digital diagnostics, still these frameworks often endure lesion noises, modality misalignment, hallucination, and missed contextual grounding in complex clinical cases. Moreover, prevailing agent systems usually depend on static and non-adaptable pipelines and lack the versatility necessary for complex medical reasoning. To resolve these difficulties, we present BioMed-Agent-RL, a unified medical agent that incorporates adaptive orchestration, policy, and reward-based reinforcement learning (RL) models for biomedical applications. To ensure reliability, it invokes clinical context-aware preference optimization (CPO), direct preference optimization (DPO), and group relative policy optimization (GRPO) with dynamic entropy regulation. This pipeline utilizes a multimodal meta-learning approach "},{"topics":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation","RL for LLM"],"source":"arxiv","title":"MCite-RL: Towards Reliable Multimodal RAG via Citation-enhanced Agentic Reinforcement Learning","upvotes":0,"id":"arxiv:2608.21808","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21808.pdf","url":"https://arxiv.org/abs/2608.21808","arxiv":"https://arxiv.org/abs/2608.21808","tags":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"authors":["Suifeng Zhao","Zida Liu","Xinyu Lei","Lei Sun","Jun Gao","Sujian Li"],"abstract":"Multimodal Retrieval-Augmented Generation (RAG) with visual citation is crucial for ensuring the traceability and verifiability of MLLMs. However, current RAG and SFT-based methods struggle to achieve robust cross-modal reasoning, causing imprecise visual citations or decoupling between the citation and the generated answers. To address these limitations, we propose MCite-RL, a citation-enhanced agentic reinforcement learning framework designed for reliable multimodal RAG. MCite-RL introduces an Agentic Refinement module for visual citation that employs iterative retrieval, reasoning, and recursive cropping to progressively narrow the search space, transforming citation into a dynamic, evidence-driven reasoning process rather than a static step. Furthermore, we incorporate a Citation-enhanced Reward mechanism that integrates both process-level and outcome-level feedback within a reinforc"},{"topics":["Post-Training","LLM Training","Tool Use","Reasoning","Fine-tuning","RL for LLM"],"source":"arxiv","title":"Think with Structured Grounding: Perceptual Reinforcement Learning for Chart and Visual-Tabular Understanding","upvotes":0,"id":"arxiv:2608.22429","announceDate":"2026-08-25","submittedDate":"2026-08-23","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22429.pdf","url":"https://arxiv.org/abs/2608.22429","arxiv":"https://arxiv.org/abs/2608.22429","tags":["Post-Training","LLM Training","Tool Use","Reasoning","Fine-tuning"],"authors":["Changjiang Jiang","Qiannian Zhao","Lei Xin","Jinxiang Xie","Preslav Nakov","Zhuohan Xie"],"abstract":"Multimodal Large Language Models (MLLMs) capable of thinking with images often rely on external tools for fine-grained perception. However, this reliance introduces significant inference latency and fails to effectively resolve the spatial-structural gap-a fundamental challenge in text-dense and structurally relational visuals (e.g., charts and visual tables) where strict relative spatial arrangements bind textual elements. Without external tools, standard MLLMs struggle with such fine-grained visual reasoning tasks. To address these issues, we propose Think with Structured Grounding (TwSG), a novel fine-grained image perception framework designed to internalize complex images's tool-use capabilities within the model. TwSG distills the benefits of multi-step reasoning and micro-cropping into a single efficient forward pass during inference. Specifically, we use an MLLM to identify key re"},{"topics":["Post-Training","VLM Training","Reasoning","Hallucination","Evaluation","RL for LLM"],"source":"arxiv","title":"Perturb the Thought, Not the Pixels: Latent-Space Rollout Diversification for Reinforcement Learning of Vision-Language Models","upvotes":0,"id":"arxiv:2608.21595","announceDate":"2026-08-25","submittedDate":"2026-08-21","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21595.pdf","url":"https://arxiv.org/abs/2608.21595","arxiv":"https://arxiv.org/abs/2608.21595","tags":["Post-Training","VLM Training","Reasoning","Hallucination","Evaluation"],"authors":["Michael Jerge","Joseph Pelczar","Justin Downes"],"abstract":"Reinforcement learning with verifiable rewards (RLVR) improves the reasoning ability of vision-language models (VLMs), and diversifying the rollouts within each optimization group amplifies its gains. Existing approaches diversify through decoding temperature or pixel-space image distortion; we ask whether the perturbation belongs in the model's latent space instead. We introduce Noise-Contrastive GRPO (NC-GRPO), which injects scale-calibrated Gaussian noise into the last hidden layer of the prompt-encoding pass for half of each rollout group, branching those rollouts from a displaced departure state. Branches that reach the answer despite the displacement are reinforced over those derailed by it, converting sensitivity at the branch point into policy-gradient signal; the objective, reward, and inference protocol are untouched. On Qwen2.5-VL-7B trained on Geometry3K, NC-GRPO significantl"},{"topics":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"source":"arxiv","title":"Thinking Beyond Videos: Unifying Video Reasoning and Deep Research for Open-World Video Agents","upvotes":0,"id":"arxiv:2608.23329","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23329.pdf","url":"https://arxiv.org/abs/2608.23329","arxiv":"https://arxiv.org/abs/2608.23329","tags":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"authors":["Wenqi Liu","Shijie Ma","Yunxiao Wang","Meng Liu","Qile Su","Han Liu","Bohan Hou","Xuanyu Zheng","Changyi Liu","Tianke Zhang","Haonan Fan","Kaiyu Jiang","Yingxin Li","Jiankang Chen","Xu Wang","Bin Wen","Tingting Gao","Han Li","Jianhua Yin","Yinwei Wei","Xuemeng Song"],"abstract":"Open-world video understanding often requires a model to locate sparse visual evidence and acquire external knowledge that is absent from the video and its parametric memory. While Thinking-with-Videos enables active temporal perception and Deep Research supports multi-step information seeking, the two capabilities are typically developed in isolation. We introduce VideoRover, a unified Video Deep Research framework that iteratively coordinates video cropping, multimodal search, and webpage browsing. Given a video-question pair, VideoRover uses each tool result to select the next action, so localized video clips guide external retrieval and retrieved evidence triggers further video inspection and verification. To develop this capability, we construct an automated data curation pipeline, producing 26K verified SFT trajectories and 3K challenging RL instances. We also introduce VideoRover-"},{"topics":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"source":"arxiv","title":"Counter with Evidence! A Multi-Agent Memory Efficient Reasoning Framework for Hate Category Informed Counterspeech Generation","upvotes":0,"id":"arxiv:2608.23152","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23152.pdf","url":"https://arxiv.org/abs/2608.23152","arxiv":"https://arxiv.org/abs/2608.23152","tags":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"authors":["Sujoy Nath","Aswini Kumar","Tanmoy Chakraborty"],"abstract":"Counterspeech effectively neutralizes the impact of online hate. Although prior work explores automated counterspeech generation, it largely emphasizes stylistic control while treating hate speech as homogeneous, overlooking that distinct forms of abuse require fundamentally different counterspeech strategies. To address this gap, we introduce FIRE (Factuality Informed Multi-Agent Reasoning Framework) that first decomposes hate speech into one of the five distinct categories (misinformation, stereotype, conspiracy, dehumanizing, non-factual), and then maps it to a targeted counterspeech style. To facilitate FIRE, we curate FactualCS, a novel dataset of $4,784$ instances that provides the annotations regarding hate categories, reasoning traces, and evidence mappings, which are critical elements for grounded generation that are missing in prior work. A comprehensive evaluation across $28$ "},{"topics":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"source":"arxiv","title":"Buried in Textual Debt: Context Pruning with Visual Evidence Preservation for MLLM Agents","upvotes":0,"id":"arxiv:2608.22963","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22963.pdf","url":"https://arxiv.org/abs/2608.22963","arxiv":"https://arxiv.org/abs/2608.22963","tags":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"authors":["Yuchen Huang","Sijia Li","Jun Zhang","Yi R. Fung"],"abstract":"Multimodal Large Language Models (MLLMs) are increasingly deployed as multi-step agents, where explicit reasoning supports task decomposition and tool coordination but also accumulates self-generated text. Over long trajectories, this text can dominate the context and suppress visual evidence, creating textual debt. We observe that reasoning becomes redundant once task-relevant visual evidence is grounded, while stale hypotheses can misguide later inference when grounding remains uncertain. Pruning must therefore remove redundant text without discarding visual evidence. We propose SPARE, a Kullback--Leibler (KL)-guided framework for pruning accumulated reasoning in multimodal tool-use agents. SPARE uses a compact task-state summary as privileged diagnostic context. For each candidate segment, it replays the same model under the original and summary-conditioned contexts. Reverse-KL diverg"},{"topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"source":"arxiv","title":"EvoWiki: Incremental State Overwriting and Traceable Question Answering for Cross-Meeting Knowledge Evolution","upvotes":0,"id":"arxiv:2608.23265","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23265.pdf","url":"https://arxiv.org/abs/2608.23265","arxiv":"https://arxiv.org/abs/2608.23265","tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Dongsheng Chen","Tianyu Wang","Wenhui Que"],"abstract":"In long-term collaboration spanning multiple meetings, factual states such as decisions and risks are continually revised, overturned, and replaced. Existing long-context methods typically stack the entire history, while many RAG and structured-memory methods organize knowledge as static or append-only facts and rely on semantic relevance at read time. Without explicit modeling of knowledge lifecycles, these approaches may retain conflicting old and new states simultaneously or discard history, leading to stale retrieval and answers that are difficult to verify. We present EvoWiki, an incremental question-answering architecture for dynamic long-form text. EvoWiki decouples offline incremental construction (BUILD) from online structured reading (READ). BUILD captures the intra-meeting micro-evolution from proposal to decision and uses entity version chains and a fine-grained State-Overwri"},{"topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"source":"arxiv","title":"Execution-Anchored Hallucination Calibration Reranking for Verilog Code Generation","upvotes":0,"id":"arxiv:2608.22938","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22938.pdf","url":"https://arxiv.org/abs/2608.22938","arxiv":"https://arxiv.org/abs/2608.22938","tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Guang Yang","Xing Hu","Xiang Chen","Terry Yue Zhuo","Xin Xia"],"abstract":"Large Language Models (LLMs) have demonstrated remarkable capabilities in code generation, yet their performance degrades significantly on low-resource Hardware Description Languages such as Verilog. While multi-candidate sampling improves the likelihood of generating correct solutions, au-tomatically selecting the optimal candidate remains an open challenge. Through a systematic empirical study across nine models and two benchmarks, we identify two critical limitations:(1) existing execution-based reranking methods, which rely on testbench pass/fail outcomes, exhibit poor domain transferability due to low-quality generated testbenches; and (2) LLM-as-a-Judge suffers from reasoning hallucination, producing incon-sistent judgments for execution-equivalent code. These findings reveal two signal types with orthogonal errors: execution signals(deterministic but testbench coverage limited)and"},{"topics":["Agentic Search","Post-Training","Reasoning","Alignment","RL for LLM"],"source":"arxiv","title":"ESCRAG-R1: Retrieval-Augmented Reinforcement Learning for Emotional Support Conversation","upvotes":0,"id":"arxiv:2608.21925","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21925.pdf","url":"https://arxiv.org/abs/2608.21925","arxiv":"https://arxiv.org/abs/2608.21925","tags":["Agentic Search","Post-Training","Reasoning","Alignment","RL for LLM"],"authors":["Weichu Liu","Yuxuan Hu","Yirong Sun","Ningning Mao","Ziyun Zhang","Jian Chen","Mingyang Xu","Qishan Zhong","Chengming Li"],"abstract":"Emotional Support Conversation (ESC) systems aim to provide holistic support by balancing professional therapeutic competence with natural empathy. However, existing methods struggle to simultaneously achieve structured, stage-aware reasoning and seamless empathy-expertise alignment, often resulting in an artificial splicing of clinical strategies and generic reassurance. To overcome these limitations, we propose ESCRAG-R1, a unified framework that integrates retrieval-based psychological guidance into Group Relative Policy Optimization (GRPO). By incorporating retrieval into the reinforcement learning loop, ESCRAG-R1 transforms external knowledge into a robust learning signal that stimulates explicit internal reasoning prior to generation and fundamentally reshapes the model's internal policy. To provide the reliable supervision required for this optimization, we construct ESC-Preferenc"},{"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"source":"arxiv","title":"Is Next-Chunk Reasoning RL Really Better than SFT? Revisiting Training Strategies under no-CoT Data","upvotes":0,"id":"arxiv:2608.23256","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23256.pdf","url":"https://arxiv.org/abs/2608.23256","arxiv":"https://arxiv.org/abs/2608.23256","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Yinhao Tang","Youqing Fang","Yanan Sun","Jiangning Liu","Ziyi Wang","Xun Zhao","Weiming Zhang","Bin Liu","Kuikun Liu","Wenwei Zhang","Kai Chen"],"abstract":"Recent work proposes next-chunk reasoning RL for leveraging no-CoT data---corpora such as worked solutions and textbook derivations that contain reasoning-rich content but lack explicit chain-of-thought annotations. The method trains a model to generate implicit reasoning traces and rewards them by their ability to predict the next chunk of text. While promising, existing evaluations primarily compare against conventional SFT baselines, leaving open whether the gains come from the RL formulation itself or from more effectively exposing the model to no-CoT data. We address this question with a controlled study of next-chunk reasoning RL and a simple but previously overlooked alternative: Mixed SFT, a single supervised fine-tuning stage that jointly trains on no-CoT and long-CoT data. Despite its simplicity, Mixed SFT achieves a clearly higher post-RLVR performance ceiling than next-chunk "},{"topics":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"source":"arxiv","title":"Thinking at the Right Size: Amortized Distillation Across Post-Trained LLMs","upvotes":0,"id":"arxiv:2608.22854","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22854.pdf","url":"https://arxiv.org/abs/2608.22854","arxiv":"https://arxiv.org/abs/2608.22854","tags":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"authors":["Yan Zhou","Sara Kangaslahti","Jonathan Geuter","Nihal V. Nayak","Marco Fumero","Francesco Locatello","David Alvarez-Melis"],"abstract":"Practical deployment of large language models (LLMs) requires families of post-trained variants---instruction-tuned, reasoning-tuned, and chat-style models---each at multiple sizes to meet diverse latency and memory budgets. Producing each (variant, size) pair independently is prohibitive, so model families typically span only a handful of coarse-grained sizes per post-trained variant. Boomerang distillation (Kangaslahti et al., 2026) reduces this cost along the size axis for base models. Through model size interpolation, it constructs models of intermediate sizes from a single teacher-student pair without additional training. However, it still treats each post-trained variant as a separate object of optimization. We introduce ADAPT---Amortized Distillation Across Post-Trained LLMs---a framework for amortizing distillation across both axes of a model family: size and post-training varian"},{"topics":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"source":"arxiv","title":"Hints, Critics, and Teachers: Prior Injection for Sparse-Reward RL in Vision-Language Math Reasoning","upvotes":0,"id":"arxiv:2608.21811","announceDate":"2026-08-25","submittedDate":"2026-08-22","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.21811.pdf","url":"https://arxiv.org/abs/2608.21811","arxiv":"https://arxiv.org/abs/2608.21811","tags":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"authors":["Qiqian Fu"],"abstract":"Reinforcement learning for vision-language math reasoning starves under sparse reward: on a pool of 20,830 visual-math problems where Qwen2-VL-2B answers 3.6% of rollouts correctly, 85-97% of GRPO rollout groups are entirely wrong and contribute zero gradient. We train eleven methods under identical conditions in this regime, each injecting a different prior: text (reference-solution hints), distribution (on-policy distillation from a 7B teacher), and value (a value-pretrained critic with an MSE or HL-Gauss categorical loss). A prior helps exactly when it is delivered: the six arms whose prior effectively reaches the policy separate with no overlap from the remaining five -- the no-prior baseline and four arms whose prior is teacher-capped, gated away, or lost to a mis-parameterized critic -- both on the pooled in-domain metric and on cross-domain transfer (DynaMath). The central finding"},{"topics":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"source":"arxiv","title":"Mitigating Reasoning-Induced Misalignment via Safety-Direction Penalty","upvotes":0,"id":"arxiv:2608.23497","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23497.pdf","url":"https://arxiv.org/abs/2608.23497","arxiv":"https://arxiv.org/abs/2608.23497","tags":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"authors":["Yipeng Zhao","Qishun Yang","Shenzhe Zhu","Shu Yang","Di Wang"],"abstract":"Reasoning-Induced Misalignment, where fine-tuning on reasoning data containing no harmful content, including mathematics, code, and problem-solving with chain-of-thought traces can induce harmful behaviors of LLM, posing a serious challenge to the safety of LLM reasoning. Cross-architecture, cross-scale, and cross-dataset checks show that RIM does not always emerge. Previous work attributed RIM to neuron-level entanglement, but did not identify the geometry of the representation space underlying this entanglement or propose a training-time fix. We provide both: a representation-space analysis of RIM and the Safety-Direction Penalty (SDP), which penalizes movement along a learned safety direction during reasoning fine-tuning. The analysis extracts two activation-space directions, one encoding reasoning ability and the other safety behavior. These directions are coupled: fine-tuning that i"},{"topics":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"source":"arxiv","title":"On the Threat Model of Weird Generalization and Emergent Misalignment","upvotes":0,"id":"arxiv:2608.23476","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.23476.pdf","url":"https://arxiv.org/abs/2608.23476","arxiv":"https://arxiv.org/abs/2608.23476","tags":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"authors":["Miriam Wanner","Mark Dredze","William Walden"],"abstract":"Narrow fine-tuning on small, domain-specific datasets can produce broad and surprising changes in model behavior-a phenomenon called weird generalization (WG). Yet, it remains unclear what features of the fine-tuning data are necessary for WG to arise. Here, we address this question by investigating a range of plausibly relevant features, including dataset size, composition, language, presentation style, and novelty relative to a model's parametric knowledge. Further, since WG evaluations rely on small question sets that assess the extent of the generalization, we also analyze how sensitive this measurement is to the set of questions used. Experiments with three open-weight models on four datasets show that the degree of WG (1) depends heavily on dataset composition and language (more than on size); (2) is greater for data familiar from pretraining than for novel data; and (3) is sensiti"},{"topics":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"source":"arxiv","title":"WADE: A Reasoning-Annotated Benchmark for Multi-Instance Floating-Waste Grounding with Compact Vision-Language Models","upvotes":0,"id":"arxiv:2608.22950","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22950.pdf","url":"https://arxiv.org/abs/2608.22950","arxiv":"https://arxiv.org/abs/2608.22950","tags":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"authors":["Md. Asaduzzaman Shuvo","Ahsan Farabi","Md. Abdul Ahad Minhaz","Mahedi Hasan","Israt Khandaker","Ibrahim Khalil Shanto","Muhammad Nomani Kabir"],"abstract":"Floating waste in inland waterways threatens aquatic ecosystems and requires timely monitoring under cluttered, multi-object conditions. Existing aquatic-waste datasets provide limited geographic coverage, sparse multi-instance annotations, and little supervision beyond boxes and labels. Compact vision-language models (VLMs) therefore remain insufficiently evaluated for jointly localizing, classifying, counting, and explaining floating waste. We introduce WADE, a reasoning-annotated benchmark containing 2,167 images from rural Bangladesh, 13,608 bounding boxes, and ten waste categories. Each annotation is associated with class-level recognition rules covering visual cues, likely confusions, and discriminative features. We evaluate six VLMs under zero-shot, two-shot, reasoning-guided, and fine-tuned settings using detection, counting, and hallucination metrics. For resource-efficient adap"},{"topics":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"source":"arxiv","title":"Can We Perform Online RL for Image Editing without Editing Rewards?","upvotes":0,"id":"arxiv:2608.22780","announceDate":"2026-08-25","submittedDate":"2026-08-24","date":"2026-08-25","pdf":"https://arxiv.org/pdf/2608.22780.pdf","url":"https://arxiv.org/abs/2608.22780","arxiv":"https://arxiv.org/abs/2608.22780","tags":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"authors":["Qichao Ma","Jikang Cheng","Ling Liang","Zhaofei Yu","Tiejun Huang","Renye Yan"],"abstract":"Reinforcement learning (RL) enables direct preference optimization for image editing through editing-specific rewards, which remain less developed due to costly triplet supervision and complex task-dependent calibration. In contrast, text-to-image (T2I) generation benefits from a mature and diverse reward ecosystem spanning semantic alignment, aesthetics, realism, glyph shape, and other visual preferences. Extending this ecosystem to image editing would substantially broaden the range of visual preferences accessible to RL-based optimization, prompting the central question: \\emph{Can We Perform Image Editing RL without Editing Rewards?} In this paper, we argue that the standard image editing dimensions have potential to be mapped to the T2I reward space: image quality can transfer directly, prompt following can be aligned through a description of the desired visual state, and reference c"}],"archive":[],"latestPath":"data/latest.json"};
